(149, 'quotation', 'tur', 'Thank you for your interest in our products !', '<p><b><span style=\"font-size:14px;\">Dear {contact_name},</span></b></p><p>Thank you for your interest in our products. Your quotation number is {quotation_number}.</p><p>Please let us know if you have any questions or concerns regarding your quotation. We are here to assist you.</p><p>Best regards,</p><p><b><span style=\"font-size:14px;\">{business_name}</span></b></p>', '2026-08-29 11:13:02.000000', '2026-08-29 11:13:02.000000', NULL),
(150, 'payment_received', 'tur', 'Payment Received - Thank You', '<p><b><span style=\"font-size:14px;\">Dear {contact_name},</span></b></p><p>Thank you for making your payment. We have received it and it has been processed successfully.</p><p>If you have any further questions or concerns, please don\'t hesitate to reach out to us. We are always here to help.</p><p>Best regards,</p><p><b><span style=\"font-size:14px;\">{business_name}</span></b></p>', '2026-08-29 11:13:02.000000', '2026-08-29 11:13:02.000000', NULL),
(151, 'purchase', 'tur', 'Thank You for Your Cooperation and Service', '<p><b><span style=\"font-size:14px;\">Dear {contact_name},</span></b></p><p>I recently made a purchase from your company and I wanted to thank you for your cooperation and service. My invoice number is {invoice_number} .</p><p>If you have any questions or concerns regarding my purchase, please don\'t hesitate to contact me. I am here to make sure I have a positive experience with your company.</p><p>Best regards,</p><p><b><span style=\"font-size:14px;\">{business_name}</span></b></p>', '2026-08-29 11:13:02.000000', '2026-08-29 11:13:02.000000', NULL),
(152, 'payment_sent', 'tur', 'Payment Sent - Thank You for Your Service', '<p><b><span style=\"font-size:14px;\">Dear {contact_name},</span></b></p><p>We have just sent the payment . We appreciate your prompt attention to this matter and the high level of service you provide.</p><p>If you need any further information or clarification, please do not hesitate to reach out to us. We are here to help.</p><p>Best regards,</p><p><b><span style=\"font-size:14px;\">{business_name}</span></b></p>', '2026-08-29 11:13:02.000000', '2026-08-29 11:13:02.000000', NULL),
(153, 'booking', 'tur', 'Your Booking Confirmation', '<p><b><span style=\"font-size:14px;\">Dear {contact_name},</span></b></p><p>Your booking has been confirmed. Booking number: {booking_number}.</p><p><span style=\"font-size:14px;\">Date: {booking_date}<br>Time: {start_time} - {end_time}<br>Service: {service_name}</span></p><p>If you have any questions, please don\'t hesitate to contact us.</p><p>Best regards,</p><p><b><span style=\"font-size:14px;\">{business_name}</span></b></p>', '2026-08-29 11:13:02.000000', '2026-08-29 11:13:02.000000', NULL),
(154, 'asset_validation_due', 'tur', 'Asset validation due: {asset_name}', '<p>The following asset is due for validation (or is overdue). Please verify the tool or equipment.</p><p><b>Asset:</b> {asset_name} ({asset_tag})<br><b>Next validation date:</b> {next_validation}</p><p><a href=\"{asset_edit_url}\">View / Edit asset</a></p><p>Best regards,<br><b>{business_name}</b></p>', '2026-08-29 11:13:02.000000', '2026-08-29 11:13:02.000000', NULL),
