(151, 'payment_received', 'tur', 'Dear {contact_name},\nThank you for making your payment. We have received it and it has been processed successfully.\nIf you have any further questions or concerns, please don\'t hesitate to reach out to us. We are always here to help.\nBest regards,\n{business_name}', '2026-08-29 11:13:04.000000', '2026-08-29 11:13:04.000000', NULL),
(152, 'payment_sent', 'tur', 'Dear {contact_name},\nWe have just sent the payment . We appreciate your prompt attention to this matter and the high level of service you provide.\nIf you need any further information or clarification, please do not hesitate to reach out to us. We are here to help.\nBest regards,\n{business_name}', '2026-08-29 11:13:04.000000', '2026-08-29 11:13:04.000000', NULL),
(153, 'subscription_reminder', 'tur', 'Hello {client_name},\nThis is a reminder from {business_name} that your subscription will renew automatically on {next_billing_date}. \nPlease ensure your payment method is up-to-date to avoid interruptions.\nThank you!', '2026-08-29 11:13:04.000000', '2026-08-29 11:13:04.000000', NULL),
