(3804, 'Ind', 'Units_Guide_Base', 'Satuan dasar: biarkan \"Satuan Dasar\" kosong. Stok selalu dihitung dalam satuan ini, misalnya Pcs.', 0, 0, '2026-08-29 11:12:19.000000', '2026-08-29 11:12:19.000000'),
(3805, 'Ind', 'Units_Guide_Sub', 'Sub-satuan: pilih \"Satuan Dasar\", lalu gunakan \"Operator\" dan \"Nilai Operasi\" untuk mengonversinya ke satuan dasar tersebut.', 0, 0, '2026-08-29 11:12:19.000000', '2026-08-29 11:12:19.000000'),
(3806, 'Ind', 'Units_Guide_Example_Multiply', 'Contoh: Dus dengan satuan dasar Pcs, operator * dan nilai 12. Menjual 1 Dus mengurangi 12 Pcs dari stok.', 0, 0, '2026-08-29 11:12:19.000000', '2026-08-29 11:12:19.000000'),
(3807, 'Ind', 'Units_Guide_Example_Divide', 'Contoh: Gram dengan satuan dasar Kilogram, operator / dan nilai 1000. Menjual 500 Gram mengurangi 0,5 Kilogram dari stok.', 0, 0, '2026-08-29 11:12:19.000000', '2026-08-29 11:12:19.000000'),
(3808, 'Ind', 'Units_Guide_Note', 'Hanya satuan dasar yang dapat dipilih sebagai \"Satuan Dasar\", dan satuan tidak dapat dihapus selama masih ada sub-satuan yang memakainya.', 0, 0, '2026-08-29 11:12:19.000000', '2026-08-29 11:12:19.000000'),
(3809, 'Ind', 'Amount_Paid', 'Jumlah Dibayar', 0, 0, '2026-08-29 11:12:19.000000', '2026-08-29 11:12:19.000000'),
(3810, 'Ind', 'Payment_Amounts_Help', 'Jumlah Dibayar melunasi saldo dan mengurangi Sisa Tagihan. Jumlah Diterima adalah uang tunai yang diserahkan: hanya dipakai untuk menghitung Kembalian dan tidak mengubah Sisa Tagihan.', 0, 0, '2026-08-29 11:12:19.000000', '2026-08-29 11:12:19.000000'),
(3811, 'Ind', 'Show_Tax_Desc', 'Pajak yang dikenakan pada seluruh penjualan saat checkout, dicetak sebagai baris \"Pajak Pesanan\" tersendiri pada bagian total.', 0, 0, '2026-08-29 11:12:19.000000', '2026-08-29 11:12:19.000000'),
