(11539, 'ba', 'Resize_Product_Images', 'পণ্যের ছবি রিসাইজ করুন', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11540, 'ba', 'Resize_Product_Images_Help', 'সংরক্ষণের সময় পণ্য, ভ্যারিয়েন্ট ও গ্যালারির ছবি ছোট করা হয়। এটি বন্ধ রাখলে আপলোড করা ফাইল মূল রেজোলিউশনেই সংরক্ষিত হবে (ফাইল বড় হবে, পেজ ধীর হবে)।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11541, 'ba', 'Product_Image_Max_Size', 'পণ্যের ছবির সর্বোচ্চ আকার', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11542, 'ba', 'Product_Image_Max_Size_Help', 'সংরক্ষিত পণ্যের ছবির দীর্ঘতম দিক পিক্সেলে কত হবে। অ্যাসপেক্ট রেশিও অপরিবর্তিত থাকে এবং ছোট ছবি কখনও বড় করা হয় না।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
