(11545, 'ba', 'Image_Max_2MB', 'ছবিটি অবশ্যই 2 MB বা তার কম হতে হবে।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11546, 'ba', 'Units_Guide_Title', 'ইউনিট কীভাবে কাজ করে', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11547, 'ba', 'Units_Guide_Base', 'বেস ইউনিট: \"বেস ইউনিট\" ঘরটি ফাঁকা রাখুন। স্টক সবসময় এই ইউনিটেই গণনা করা হয়, যেমন পিস।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11548, 'ba', 'Units_Guide_Sub', 'সাব-ইউনিট: একটি \"বেস ইউনিট\" বেছে নিন, তারপর \"অপারেটর\" ও \"অপারেশন ভ্যালু\" দিয়ে সেটিকে ওই বেস ইউনিটে রূপান্তর করুন।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11549, 'ba', 'Units_Guide_Example_Multiply', 'উদাহরণ: একটি বক্স, যার বেস ইউনিট পিস, অপারেটর * এবং ভ্যালু 12। 1 বক্স বিক্রি করলে স্টক থেকে 12 পিস কমে।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11550, 'ba', 'Units_Guide_Example_Divide', 'উদাহরণ: একটি গ্রাম, যার বেস ইউনিট কিলোগ্রাম, অপারেটর / এবং ভ্যালু 1000। 500 গ্রাম বিক্রি করলে স্টক থেকে 0.5 কিলোগ্রাম কমে।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11551, 'ba', 'Units_Guide_Note', 'শুধু বেস ইউনিটগুলোকেই \"বেস ইউনিট\" হিসেবে বেছে নেওয়া যায়, এবং কোনো ইউনিটের সাব-ইউনিট থাকা অবস্থায় সেটি মুছে ফেলা যায় না।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11552, 'ba', 'Amount_Paid', 'পরিশোধিত পরিমাণ', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11553, 'ba', 'Payment_Amounts_Help', 'পরিশোধিত পরিমাণ বকেয়া নিষ্পত্তি করে এবং বাকি কমায়। প্রাপ্ত পরিমাণ হলো হাতে নেওয়া নগদ: এটি শুধু ফেরত দেওয়ার ভাংতি হিসাব করতে ব্যবহৃত হয় এবং বাকি পরিবর্তন করে না।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11554, 'ba', 'Show_Tax_Desc', 'চেকআউটে পুরো বিক্রয়ের ওপর প্রযোজ্য কর, যা মোট অংশে আলাদা \"অর্ডার ট্যাক্স\" লাইন হিসেবে ছাপা হয়।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11555, 'ba', 'Show_Items_Tax_Desc', 'প্রতিটি পণ্যের নিজস্ব করের যোগফল, যা \"মোট আইটেম ট্যাক্স\" লাইন হিসেবে ছাপা হয়। চালু থাকলে সাবটোটাল এই কর ছাড়াই দেখানো হয়।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11556, 'ba', 'Show_Discount_Desc', 'পুরো বিক্রয়ের ওপর দেওয়া ছাড় (পয়েন্ট ছাড়সহ), যা মোট অংশে আলাদা লাইন হিসেবে ছাপা হয়।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
(11557, 'ba', 'Show_Product_Discount_Desc', 'প্রতিটি পণ্যের নিজস্ব ছাড়, যা আইটেম তালিকায় ওই পণ্যের নিচে ছাপা হয়।', 0, 0, '2026-08-29 11:12:20.000000', '2026-08-29 11:12:20.000000'),
